#include <vector>
#include <chrono>
#include <cstdio>
#include <cmath>
#include "lebesgue-cuda/kernels.cu"
#include "fixture_nodes.h"
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
int main(int argc,char**argv){int nfun=argc>1?atoi(argv[1]):65,repeat=argc>2?atoi(argv[2]):3;std::vector<double>xfun(nfun),expected;for(int i=0;i<nfun;i++)xfun[i]=-1.+2.*i/(nfun-1);double*df;cudaMalloc(&df,nfun*8);cudaMemcpy(df,xfun.data(),nfun*8,cudaMemcpyHostToDevice);std::vector<double*>xs,interps,maxima;for(const auto&x:NODE_SETS){int n=x.size();std::vector<double>interp(n*nfun),totals(nfun,0.);for(int j=0;j<nfun;j++)for(int a=0;a<n;a++){double v=1.;for(int z=0;z<n;z++)if(a!=z)v=v*(xfun[j]-x[z])/(x[a]-x[z]);interp[a*nfun+j]=v;totals[j]+=fabs(v);}expected.insert(expected.end(),interp.begin(),interp.end());double max=0;for(double t:totals)max=fmax(max,t);expected.push_back(max);double*dx,*di,*dm;cudaMalloc(&dx,n*8);cudaMalloc(&di,n*nfun*8);cudaMalloc(&dm,8);cudaMemcpy(dx,x.data(),n*8,cudaMemcpyHostToDevice);cudaMemset(dm,0,8);xs.push_back(dx);interps.push_back(di);maxima.push_back(dm);kernel<<<(nfun+255)/256,256>>>(dm,di,df,dx,n,nfun);}cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){double total=0;std::vector<double>values;for(size_t k=0;k<NODE_SETS.size();k++){int n=NODE_SETS[k].size();cudaMemset(maxima[k],0,8);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)kernel<<<(nfun+255)/256,256>>>(maxima[k],interps[k],df,xs[k],n,nfun);cudaDeviceSynchronize();total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<double>v(n*nfun+1);cudaMemcpy(v.data(),interps[k],n*nfun*8,cudaMemcpyDeviceToHost);cudaMemcpy(v.data()+n*nfun,maxima[k],8,cudaMemcpyDeviceToHost);values.insert(values.end(),v.begin(),v.end());}emit(trial,total,values,expected,repeat,1e-10,1e-12);}for(size_t k=0;k<xs.size();k++){cudaFree(xs[k]);cudaFree(interps[k]);cudaFree(maxima[k]);}cudaFree(df);return 0;}
